/**
 * Executes an array of task functions with a concurrency limit.
 * Each task is a function that returns a Promise.
 */
declare function executeWithConcurrency<T>(tasks: (() => Promise<T>)[], concurrency: number): Promise<T[]>;

type TigrisResponse<T, E = Error> = {
    data: T;
    error?: never;
} | {
    error: E;
    data?: never;
};

type TigrisStorageResponse<T, E = Error> = TigrisResponse<T, E>;

type UploadOptions = {
    access?: 'public' | 'private';
    addRandomSuffix?: boolean;
    allowOverwrite?: boolean;
    contentType?: string;
    contentDisposition?: 'attachment' | 'inline';
    url?: string;
    multipart?: boolean;
    partSize?: number;
    /**
     * Maximum number of concurrent part uploads for multipart uploads
     * @default 4
     */
    concurrency?: number;
    onUploadProgress?: (progress: UploadProgress) => void;
};
type UploadProgress = {
    loaded: number;
    total: number;
    percentage: number;
};
type UploadResponse = {
    contentDisposition?: string;
    contentType?: string;
    modified: Date;
    name: string;
    size: number;
    url: string;
};
declare function upload(name: string, data: File | Blob, options?: UploadOptions): Promise<TigrisStorageResponse<UploadResponse, Error>>;

export { type UploadOptions, type UploadProgress, type UploadResponse, executeWithConcurrency, upload };
